import * as React from 'react';
import { useState } from 'react';
import { useDispatch } from 'react-redux';

import { Stack } from '@mui/material';

import NewGameCategories from 'components/menu/NewGameCategories';
import NewGameOptions from 'components/menu/NewGameOptions';
import { chooseGameCategory } from 'store/actions';
import { useGameConfig, useGameOptions } from 'store/selector';

const NewGame = (props) => {
    const { cssTransition } = props;
    const dispatch = useDispatch();
    const gameOptions = useGameOptions();
    const gameConfig = useGameConfig();

    const [step, setStep] = useState(0);
    const [gameCategoryKey, setGameCategoryKey] = useState(
        (gameOptions && gameOptions.gameMode) || gameConfig?.gameCategories[0].key
    );

	if (!gameConfig) {
		return null;
	}

    const handleClickGameCategory = (gameCategoryKey) => {
        setGameCategoryKey(gameCategoryKey);
        setStep(1);
        dispatch(chooseGameCategory(gameCategoryKey));
    };
    const handleClickChangeGameCategory = () => {
        setStep(0);
    };

    return (
        <>
            <Stack
                alignItems="center"
                direction="column"
                justifyContent="center"
                maxWidth="100%"
                height="100%"
                flexGrow={1}
                gap={3}
                sx={{
                    ...cssTransition,
                }}
            >
                {step === 0 ? (
                    <NewGameCategories handleClickGameCategory={handleClickGameCategory} />
                ) : step === 1 ? (
                    <NewGameOptions
                        gameCategoryKey={gameCategoryKey}
                        handleClickChangeGameCategory={handleClickChangeGameCategory}
                    />
                ) : null}
            </Stack>
        </>
    );
};

export default NewGame;
