import { useTheme } from '@emotion/react';
import { DIFFICULTY_FLASHCARD, DIFFICULTY_NORMAL, FULL, SHORT } from 'config/baseConfig';
import * as React from 'react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';

import {
    Button,
    Card,
    Grow,
    InputLabel,
    Stack,
    Switch,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Typography,
    alpha,
} from '@mui/material';

import MainButton from 'components/ui/MainButton';
import OptionRow from 'components/ui/OptionRow';
import { getRegions } from 'data/data';
import { chooseGameMode, startGame } from 'store/actions';
import {
    useGameConfig,
    useGameOptions,
    useLanguage,
    useLastGameCategory,
    useLastGameMode,
    useShowAdvancedOptions,
} from 'store/selector';
import { Spacer, getGameSVG, pxToRem } from 'util/util';

const getGameModeKey = (gameCategory, lastGameModeKey, lastGameCategoryKey) => {
	return lastGameModeKey ||
        (gameCategory.modes.find((mode) => mode.key === lastGameCategoryKey) || gameCategory.modes[0]).key
}
const getDifficulty = (gameOptions, selectedGameMode) => {
	return (gameOptions &&
		(gameOptions.difficultyLevel === DIFFICULTY_FLASHCARD && !selectedGameMode.hasFlashCardDifficulty
			? DIFFICULTY_NORMAL
			: gameOptions.difficultyLevel)) ??
		DIFFICULTY_NORMAL;
}
const getIndependantOnly = (gameOptions, gameCategory) => {
	return !!gameCategory.canChooseIndependant ? (gameOptions ? gameOptions.independantOnly : true) : false;
}

const NewGameOptions = (props) => {
    const { handleClickChangeGameCategory, gameCategoryKey } = props;

    const dispatch = useDispatch();
    const theme = useTheme();
    const { t, i18n } = useTranslation();
    const language = useLanguage();

    const gameConfig = useGameConfig();
    const gameOptions = useGameOptions();
    const lastGameCategoryKey = useLastGameCategory();
    const lastGameModeKey = useLastGameMode();
    const showAdvancedOptions = useShowAdvancedOptions();
    const gameCategory = gameConfig.gameCategories.find((g) => g.key === gameCategoryKey);

    const [gameModeKey, setGameModeKey] = useState(getGameModeKey(gameCategory, lastGameModeKey, lastGameCategoryKey));
    const [selectedGameMode, setSelectedGameMode] = useState(gameCategory.modes.find((mode) => mode.key === gameModeKey));

    const [gameLength, setGameLength] = useState((gameOptions && gameOptions.gameLength) || SHORT);
    const [region, setRegion] = useState(gameCategory.canChooseRegion ? gameOptions?.region || 'all' : 'all');
    const [difficultyLevel, setDifficultyLevel] = useState(getDifficulty(gameOptions, selectedGameMode));
    const [independantOnly, setIndependantOnly] = useState(getIndependantOnly(gameOptions, gameCategory));
    // const [hideBackgroundMap, setHideBackgroundMap] = useState((gameOptions && gameOptions.hideBackgroundMap) ?? false);

    const regions = getRegions();

    const handleChangeMode = (event) => {
		let _gameModeKey = event.target.value;
		let _selectedGameMode = gameCategory.modes.find((mode) => mode.key === _gameModeKey);
		setGameModeKey(_gameModeKey);
		setSelectedGameMode(_selectedGameMode);
		setDifficultyLevel(getDifficulty(undefined, _selectedGameMode));
        dispatch(chooseGameMode(_gameModeKey));
    };

    const handleChangeLength = (event) => {
        setGameLength(event.target.value);
    };

    const handleChangeIndependant = (event) => {
        setIndependantOnly(event.target.checked);
    };

    const handleChangeRegion = (event) => {
        setRegion(event.target.value);
    };

    const handleChangeDifficultyLevel = (event) => {
        setDifficultyLevel(parseInt(event.target.value));
    };

    // const handleClickHideBackgroundMap = (event) => {
    //     setHideBackgroundMap(event.target.checked);
    // };

    const handleClickStart = () => {
        dispatch(startGame(gameModeKey, region, difficultyLevel, independantOnly, gameLength)); // , hideBackgroundMap
    };

    const optionFlashcard = gameConfig.difficultyLevels.find((option) => option.key === DIFFICULTY_FLASHCARD);

    return (
        <Grow in={true}>
            <Card
                aria-label={t('Options')}
                sx={{
                    textAlign: 'center',
                    minWidth: pxToRem(240),
                    position: 'relative',
					'.MuiFormLabel-root': {
						lineHeight: `${pxToRem(40)}`,
					},
                }}
            >
                <Stack spacing={1.5}>
                    <Button
                        variant="mode"
                        size="medium"
                        py={pxToRem(12)}
                        sx={{
                            svg: {
                                color: theme.palette.secondary.contrast,
                                height: pxToRem(36),
                                width: pxToRem(36),
                                fill: 'currentColor',
                                mr: pxToRem(12),
                                filter: `drop-shadow(2px 2px 0px ${alpha(theme.palette.shadow, 0.15)})`,
                            },
                            mb: pxToRem(6),
                        }}
                        onClick={handleClickChangeGameCategory}
                    >
                        {getGameSVG(gameCategoryKey)}
                        <Typography
                            variant="h2"
                            display="block"
                            color="secondary.contrast"
                            fontSize={pxToRem(24)}
                            lineHeight={pxToRem(40)}
                            mr={pxToRem(12)}
                            sx={{
                                textShadow: `2px 2px 0px ${alpha(theme.palette.shadow, 0.1)}`,
                            }}
                        >
                            {gameCategory.name[i18n.language]}
                        </Typography>
                    </Button>
					{language === 'fra' && (gameCategory.notTranslated || gameCategory.semiTranslated) && (
						<Typography
							display="flex"
							flexDirection="row"
							justifyContent="center"
							alignItems="center"
							mb={pxToRem(-4)}
							sx={{
								fontSize: pxToRem(12),
								fontStyle: 'italic',
								// fontWeight: 800,
								width: "100%",
								// opacity: 0.75,
							}}
						>
							<span>* {t('eng')}{gameCategory.semiTranslated ? ` / ${t('fra')}` : null}</span>
						</Typography>
					)}
                    <Spacer height={1} />
                    {gameCategory.modes.length > 1 && (
                        <OptionRow>
                            <InputLabel htmlFor="Mode">{t('Variant')}:</InputLabel>
                            <ToggleButtonGroup
                                id="Mode"
                                name="Mode"
                                color="secondary"
                                value={gameModeKey}
                                exclusive
                                onChange={handleChangeMode}
                                size="small"
                                sx={{
                                    justifyContent: 'flex-end',
                                }}
                            >
                                {gameCategory.modes.map((m) => (
                                    <ToggleButton key={m.key} value={m.key}>
                                        {m?.name[i18n.language]}
                                    </ToggleButton>
                                ))}
                            </ToggleButtonGroup>
                        </OptionRow>
                    )}
                    {gameCategory.canChooseRegion && (
                        <OptionRow>
                            <InputLabel htmlFor="Region">{t('Region')}:</InputLabel>
                            <TextField
                                id="Region"
                                name="Region"
                                onChange={handleChangeRegion}
                                required
                                select
                                size="small"
                                SelectProps={{ native: true }}
                                value={region}
                                sx={{
                                    mt: 0,
                                }}
                            >
                                <option key="all" value="all">
                                    {t('World')}
                                </option>
                                {Object.values(regions)
                                    .filter((r) => !!r.subregions)
                                    .map((option) =>
                                        option.code === 'AN' ? null : (
                                            <option key={option.code} value={option.code}>
                                                {option[i18n.language]}
                                            </option>
                                        )
                                    )}
                            </TextField>
                        </OptionRow>
                    )}
                    <OptionRow>
                        <InputLabel htmlFor="Length">{t('Length')}:</InputLabel>
                        <ToggleButtonGroup
                            id="Length"
                            name="Length"
                            color="secondary"
                            value={gameLength}
                            exclusive
                            onChange={handleChangeLength}
                            size="small"
                            sx={{
                                justifyContent: 'flex-end',
                            }}
                        >
                            <ToggleButton value={SHORT} size="small">
                                {t('Short')}
                            </ToggleButton>
                            <ToggleButton value={FULL} size="small">
                                {t('Long')}
                            </ToggleButton>
                        </ToggleButtonGroup>
                    </OptionRow>
                    <OptionRow>
                        <InputLabel htmlFor="Difficulty">{t('Difficulty')}:</InputLabel>
                        <ToggleButtonGroup
                            id="Difficulty"
                            name="Difficulty"
                            color="secondary"
                            value={difficultyLevel}
                            exclusive
                            onChange={handleChangeDifficultyLevel}
                            aria-label={t('Difficulty')}
                            size="small"
                            sx={{
                                justifyContent: 'flex-end',
                                flexWrap: 'wrap',
                                maxWidth: '210px',
                            }}
                        >
                            {gameConfig.difficultyLevels
                                .filter((option) => option.key !== DIFFICULTY_FLASHCARD)
                                .map((option) => (
                                    <ToggleButton key={option.key} value={option.key} disabled={option.disabled}>
                                        {t(option.name)}
                                    </ToggleButton>
                                ))}
                            {showAdvancedOptions && selectedGameMode.hasFlashCardDifficulty && (
                                <ToggleButton
                                    key={optionFlashcard.key}
                                    value={optionFlashcard.key}
                                    disabled={optionFlashcard.disabled}
                                >
                                    {t(optionFlashcard.name)}
                                </ToggleButton>
                            )}
                        </ToggleButtonGroup>
                    </OptionRow>
                    {showAdvancedOptions && gameCategory.canChooseIndependant && (
                        <OptionRow>
                            <InputLabel htmlFor="Independent" sx={{ lineHeight: `${pxToRem(28)} !important` }}>{t('Independent countries only')}:</InputLabel>
                            <Switch
                                id="Independent"
                                name="Independent"
                                checked={independantOnly}
                                onChange={handleChangeIndependant}
                                sx={{
                                    mt: pxToRem(3),
                                    mr: 0,
                                    mb: 0,
                                    ml: 0, // pxToRem(12),
                                }}
                            />
                        </OptionRow>
                    )}
                    {/*showAdvancedOptions && gameCategory.canDisableMapBackground && (
                        <OptionRow>
                            <InputLabel htmlFor="HideBackgroundMap" sx={{ lineHeight: `${pxToRem(28)} !important` }}>{t('Hide map background')}:</InputLabel>
                            <Switch
                                id="HideBackgroundMap"
                                name="HideBackgroundMap"
                                checked={hideBackgroundMap}
                                onChange={handleClickHideBackgroundMap}
                                sx={{
                                    mt: pxToRem(3),
                                    mr: 0,
                                    mb: 0,
                                    ml: 0, // pxToRem(12),
                                }}
                            />
                        </OptionRow>
                    )*/}
                    <Spacer height={1} />
                    <MainButton
                        buttonP={{
                            color: 'primary',
                            size: 'large',
                            onClick: handleClickStart,
                            mt: pxToRem(16),
                        }}
                    >
                        {t('Start Game')}
                    </MainButton>
                </Stack>
            </Card>
        </Grow>
    );
};

export default NewGameOptions;
